    $user=get_userdata($id);
    if(!$user || $user->to_array()!==$before['data']) { return false; }
    $meta=get_user_meta($id); $wanted=$before['meta'];
    if(in_array($login,array(),true)) {
        foreach(array() as $key) { unset($meta[$key],$wanted[$key]); }
    }
    if($meta!==$wanted) { return false; }
} return true;

